package org.sleepwell.app;

import android.app.*;
import android.os.*;
import android.widget.*;
import java.util.*;

/** Saved schedule plus an explicit visible arm action; rendering and saving never request vibration. */
public final class DreamCueActivity extends Activity {
    private final Handler main=new Handler(Looper.getMainLooper());private DreamCueSettings saved;private boolean enabled,resumed,dirty;private int hours,minutes,count;private long revision;private String error="",operation,last="";
    @Override public void onCreate(Bundle state){super.onCreate(state);RecordUi.review(this);reload();if(state!=null){enabled=state.getBoolean("enabled");hours=state.getInt("hours",4);minutes=state.getInt("minutes",30);count=state.getInt("count",3);revision=state.getLong("revision");dirty=state.getBoolean("dirty");error=state.getString("error","");operation=state.getString("operation");}if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,this::finish);render();}
    private void reload(){try{saved=DreamCueSettings.load(this);enabled=saved.enabled;hours=saved.hours;minutes=saved.minutes;count=saved.count;revision=saved.revision;dirty=false;error="";}catch(RuntimeException problem){saved=null;error=problem.getMessage();}}
    private void render(){DreamCues.State status=DreamCues.state();DreamCues.Manual manual=DreamCues.manual();LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);RecordUi.header(body,"Timed dream cues",this::finish);Design.space(body,14);Design.text(body,"Gentle reminders during your night",21,600,Design.INK);Design.space(body,8);Design.text(body,"A single requested low vibration at chosen elapsed times. This is not REM detection and does not promise lucid dreaming. Cues may wake you.",13,400,Design.MUTED);Design.space(body,16);if(saved==null){Design.text(body,error,14,500,Design.BROWN);Design.button(body,"Reload saved schedule",true,()->{reload();render();});return;}
        Switch toggle=Design.toggle(body,"Enable timed cues","Saving enables the option only; Arm tonight is still required.",enabled,on->{enabled=on;dirty=true;});toggle.setEnabled(operation==null);Design.space(body,10);PlanActivity.detail(body,"clock","First cue after active tracking",null,hours+" h",()->choose("hours"));PlanActivity.detail(body,"clock","Then repeat every",null,minutes+" min",()->choose("minutes"));PlanActivity.detail(body,"clock","Maximum requests tonight",null,""+count,()->choose("count"));Design.space(body,8);Design.text(body,"Elapsed active recording time is used. Pause or saved schedule changes cancel the remaining schedule. Missed requests are skipped; each night can be armed once.",12,400,Design.MUTED);Design.space(body,12);String support=DreamCues.support(this);if(!support.isEmpty())Design.text(body,support,13,500,Design.BROWN);Design.text(body,"Requested pulse: 120 ms at low amplitude. Device settings determine actual strength; alarm-class vibration may be allowed through Do Not Disturb.",11,400,Design.MUTED);Design.space(body,16);
        if(status!=null){Design.text(body,title(status.phase),22,600,Design.INK);Design.text(body,status.message,13,500,Design.MUTED);PlanActivity.detail(body,"report","Requested / failed / skipped",null,status.requested+" / "+status.failed+" / "+status.skipped,null);if(status.busy&&manual!=null&&manual.session==status.session&&status.nextActive>=0)PlanActivity.detail(body,"clock","Next planned cue",null,"In "+RecordUi.duration(Math.max(0,status.nextActive-manual.active)),null);}
        Design.item(body,"report","Saved cue history","Actual claims, requests and failures",()->startActivity(RecordUi.intent(this,DreamCueHistoryActivity.class)));LinearLayout footer=RecordUi.footer(body);if(!error.isEmpty())Design.text(footer,error,13,500,Design.BROWN);if(operation!=null)Design.text(footer,"Saving schedule…",13,400,Design.MUTED);Design.button(footer,"Save cue schedule",false,this::save).setEnabled(operation==null);if(status!=null&&status.busy){String nonce=status.nonce;Design.button(footer,"Stop tonight’s cues",true,()->{DreamCues.cancel(nonce);render();});}else{String reason=manual==null?"Start an active manual night before arming.":dirty?"Save changes before arming tonight.":!saved.enabled?"Enable and save the option first.":"Only this active manual night will be armed.";Design.text(footer,reason,12,400,Design.MUTED);DreamCues.Manual expected=manual;long reviewedRevision=revision;Design.button(footer,"Arm tonight",true,()->{if(!resumed||!hasWindowFocus())return;try{DreamCues.arm(this,expected,reviewedRevision);error="";}catch(RuntimeException failure){error=failure.getMessage()==null?"Tonight’s cues could not be armed.":failure.getMessage();}render();}).setEnabled(operation==null&&manual!=null&&!dirty&&saved.enabled&&support.isEmpty());}last=signature();}
    private void choose(String field){if(operation!=null)return;if(field.equals("hours")){SleepPicker.choices(this,"First cue after active tracking",new String[]{"2 hours","3 hours","4 hours","5 hours","6 hours"},hours-2,n->{hours=n+2;dirty=true;render();});}else if(field.equals("minutes")){int selected=0;for(int i=0;i<DreamCueSettings.INTERVALS.length;i++)if(DreamCueSettings.INTERVALS[i]==minutes)selected=i;SleepPicker.choices(this,"Cue interval",new String[]{"20 minutes","30 minutes","45 minutes","60 minutes","90 minutes"},selected,n->{minutes=DreamCueSettings.INTERVALS[n];dirty=true;render();});}else SleepPicker.choices(this,"Maximum requests tonight",new String[]{"1","2","3","4","5","6"},count-1,n->{count=n+1;dirty=true;render();});}
    private void save(){if(operation!=null)return;try{new DreamCueSettings(enabled,hours,minutes,count,revision);operation=UUID.randomUUID().toString();error="";observe();render();}catch(RuntimeException invalid){error=invalid.getMessage();render();}}
    private void observe(){if(operation==null||!resumed)return;DreamCueSettings draft;try{draft=new DreamCueSettings(enabled,hours,minutes,count,revision);}catch(RuntimeException invalid){operation=null;error=invalid.getMessage();render();return;}PlanOperations.Operation action=PlanOperations.start(this,operation,app->{DreamCueSettings.save(app,draft,draft.revision);return null;});if(!action.done)return;PlanOperations.forget(operation);operation=null;if(action.error!=null){error=action.error;render();return;}long previous=revision;reload();if(saved!=null&&saved.revision!=previous)DreamCues.settingsChanged();error="Schedule saved. No cue was armed by saving.";render();}
    private String signature(){DreamCues.State value=DreamCues.state();DreamCues.Manual manual=DreamCues.manual();return (value==null?"none":value.nonce+value.phase+value.message+value.requested+value.failed+value.skipped)+(manual==null?"inactive":manual.session+":"+manual.active/1000);}
    private final Runnable poll=new Runnable(){@Override public void run(){if(!resumed)return;observe();if(!signature().equals(last))render();main.postDelayed(this,500);}};
    static String title(String state){return switch(state){case "ARMED"->"Tonight’s cues armed";case "SAVING"->"Saving tonight’s cues…";case "FINISHED"->"Timed schedule finished";case "CANCELLED"->"Tonight’s cues stopped";case "INTERRUPTED"->"Cue session interrupted";default->"Cue session needs attention";};}
    @Override protected void onResume(){super.onResume();resumed=true;main.post(poll);}@Override protected void onPause(){resumed=false;main.removeCallbacks(poll);super.onPause();}@Override protected void onDestroy(){main.removeCallbacks(poll);super.onDestroy();}@Override protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);state.putBoolean("enabled",enabled);state.putInt("hours",hours);state.putInt("minutes",minutes);state.putInt("count",count);state.putLong("revision",revision);state.putBoolean("dirty",dirty);state.putString("error",error);state.putString("operation",operation);}@Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);}
}
